const response = $input.first().json;
const videos = response.data ?? [];

return videos
  .filter(video => video.title && video.contentId)
  .map(video => ({
    json: {
      competitorId: video.competitorId,
      platform: video.platform,
      contentId: video.contentId,
      title: video.title,
      description: (video.description ?? '').slice(0, 500),
      publishedAt: video.publishedAt,
      url: video.url,
    }
  }));

const raw = $input.first().json.content;

if (!raw) {
  throw new Error('Ollama không trả về trường content');
}

let parsed;

try {
  parsed = JSON.parse(raw);
} catch (error) {
  throw new Error('Không thể phân tích JSON từ Ollama: ' + error.message);
}

if (!Array.isArray(parsed.trends)) {
  throw new Error('Kết quả AI không chứa mảng trends hợp lệ');
}

return parsed.trends.map(trend => ({
  json: {
    name: trend.name,
    score: trend.score,
    growth_rate: trend.growth_rate,
    direction: trend.direction,
    reason: trend.reason,
    evidence: trend.evidence
  }
}));

